technical_notes:
TypeScript interface (example):
interface StreamAdapter {
  connect(url: string, opts?: ConnectOpts): Promise<StreamSession>;
}
interface StreamSession {
  onChunk(cb: (chunk: ParsedChunk) => void): void;
  resume(nextOffset: number): Promise<void>;
  callTool(toolName: string, input: object, callId?: string): Promise<ToolAck>;
}
// sample usage shows async iterator wrapper over onChunk to keep existing generator-style APIs

Go pattern (example):
// Channel-based stream. shim.StreamSession has Recv() (returns Chunk, error) and Resume(offset int) error.
// Tool invocation returns ack struct with CallID and Status. Use context for cancellation and replay safety.

examples:
TypeScript minimal sample (pseudo):
const sess = await adapter.connect(endpoint, { apiKey });
for await (const chunk of sess.asAsyncIterator()) {
  if (chunk.type === 'tool_call') {
    const ack = await sess.callTool(chunk.toolName, chunk.payload, chunk.callId);
    // ack => { callId, status }
  } else {
    validateSchema(chunk.payload, toolResponseSchema);
    console.log(chunk.payload);
  }
}
// resume example:
await sess.resume(lastAckOffset + 1);

Go minimal sample (pseudo):
sess, err := shim.Connect(ctx, endpoint, token)
for {
  chunk, err := sess.Recv()
  if err != nil { break }
  switch chunk.Type {
  case ChunkTypeToolCall:
    ack, _ := sess.CallTool(chunk.ToolName, chunk.Payload, chunk.CallID)
  default:
    ValidateJSON(chunk.Payload, schema)
  }
}
// Resume:
sess.Resume(ctx, lastOffset+1)
